/**
 * 准备请求
 * - Webhook body 归一化（兼容 body 直接在顶层）
 * - Miniflux save_entry 归一化为普通 RSS 事件（在网页里点“保存文章”即可当测试按钮）
 * - 可选写文件日志（LOG_PATH 留空则关闭）
 * - 判断来源 kind，交给后面的「解析 - *」节点
 */

// ======================= 可调参数 =======================
// 文件日志：留空则关闭；开启需在 n8n 环境变量里设置 NODE_FUNCTION_ALLOW_BUILTIN=fs
const LOG_PATH = ""; // 例如 "/home/node/.n8n/reNotify_log.txt"
const LOG_MAX_BYTES = 5 * 1024 * 1024; // 日志超过该字节数即触发清理（默认 5 MB）
const LOG_KEEP_RATIO = 0.8; // 清理时保留最近内容的比例（0.8 = 约保留 80%）
// =======================================================

const str = (v) => (v === null || v === undefined ? "" : String(v));

// 日志清理：超过 LOG_MAX_BYTES 时只保留尾部 LOG_KEEP_RATIO 比例的内容
function rotateLog(fs, size) {
    if (!(LOG_MAX_BYTES > 0) || size <= LOG_MAX_BYTES) return;
    const ratio = LOG_KEEP_RATIO > 0 && LOG_KEEP_RATIO < 1 ? LOG_KEEP_RATIO : 0.8;
    const keepBytes = Math.max(0, Math.floor(LOG_MAX_BYTES * ratio));
    const start = Math.max(0, size - keepBytes);
    const length = size - start;
    const fd = fs.openSync(LOG_PATH, "r");
    let tail;
    try {
        tail = Buffer.alloc(length);
        fs.readSync(fd, tail, 0, length, start);
    } finally {
        fs.closeSync(fd);
    }
    // 丢掉可能被截断的第一行，保证日志始终是完整的 JSON 行
    const firstNewline = tail.indexOf(0x0a);
    const cut = firstNewline === -1 ? tail.length : firstNewline + 1;
    const tmpPath = `${LOG_PATH}.tmp.${Date.now()}.${Math.random().toString(36).slice(2, 6)}`;
    try {
        fs.writeFileSync(tmpPath, tail.subarray(cut));
        fs.renameSync(tmpPath, LOG_PATH);
    } catch (err) {
        try { fs.unlinkSync(tmpPath); } catch (_) {}
        throw err;
    }
}

function maybeLog(payload) {
    if (!LOG_PATH || typeof require !== "function") return;
    try {
        const fs = require("fs");
        const dir = LOG_PATH.replace(/[\\/][^\\/]*$/, "");
        if (dir) fs.mkdirSync(dir, { recursive: true });
        try {
            const stat = fs.statSync(LOG_PATH);
            if (stat.isFile()) rotateLog(fs, stat.size);
        } catch (e) {
            // 文件还不存在：首次写入
        }
        fs.appendFileSync(LOG_PATH, JSON.stringify(payload) + "\n");
    } catch (e) {
        // 日志失败不影响转发
    }
}

const input = $input.first().json || {};
let payload = input.body !== undefined ? input.body : input;
if (typeof payload === "string") {
    try {
        payload = JSON.parse(payload);
    } catch (e) {
        payload = {};
    }
}
if (!payload || typeof payload !== "object" || Array.isArray(payload)) payload = {};

const isSaveTest = payload.event_type === "save_entry" && payload.entry;
if (isSaveTest) {
    payload = {
        event_type: "save_entry",
        __test: true,
        feed: payload.entry.feed || {},
        entries: [payload.entry]
    };
}

maybeLog(payload);

// 来源识别：顺序与旧版保持一致
const type = str(payload.type);
const detectKind = () => {
    if (isSaveTest || "feed" in payload) return "rss";
    if ("data" in payload) {
        if (type.startsWith("subscribe.")) return "mp-subscribe";
        if (type === "download.added" || type === "transfer.complete") return "mp-download";
        if (type === "plugin.triggered") return "mp-plugin";
        if (type === "notice.message") return "mp-notice";
        return "mp-unknown";
    }
    if ("diun_version" in payload) return "diun";
    if (payload.days_until !== undefined) return "wallos";
    if ("alerts" in payload) return "grafana";
    if ("zerobyte_title" in payload) return "zerobyte";
    if ("title" in payload && "message" in payload && ("timestamp" in payload || "time" in payload)) return "dockhand";
    return "unknown";
};

return [{ json: { kind: detectKind(), payload } }];

/**
 * 解析 - RSS / Miniflux
 * 支持：其乐（临时工 / 购物心得等其它板块）、PT风向旗、直播间开播、Spotify 新专辑/新单曲、GitHub Releases，
 *       以及兜底的通用 RSS（FORWARD_UNKNOWN_RSS）
 * 输入：准备请求输出的 { kind, payload }
 * 输出：每个条目一条 Bark 消息
 */

// ======================= 可配置图标 =======================
// 其乐 Keylol 图标（临时工 / 购物心得等所有其乐板块共用）
const KEYLOL_ICON = "https://keylol.com/template/steamcn_metro/src/img/common/icon_with_text_256h.png";
// PT风向旗（Telegram 频道）图标
const PT_CHANNEL_ICON = ""; // 可选：填入自定义 PT 频道图标 URL
// 直播间开播提醒图标（B站 / 斗鱼 / 虎牙等）
const LIVE_STREAM_ICON = ""; // 可选：填入自定义直播开播图标 URL
// Spotify 艺人专属头像（键名用小写；新增艺人直接追加，未配置时仍会正常推送标题）
const SPOTIFY_ARTIST_ICONS = {
  // 可选：按艺人名（小写）配置专属封面图标，例如：
  // "artist name": "https://your-image-host.example.com/icons/artist.jpg"
};
// =========================================================

const str = (v) => (v === null || v === undefined ? "" : String(v));
let testMode = false;
const utf8Bytes = (ch) => {
    const cp = ch.codePointAt(0);
    if (cp <= 0x7f) return 1;
    if (cp <= 0x7ff) return 2;
    if (cp <= 0xffff) return 3;
    return 4;
};
const clipUtf8 = (text, maxBytes, suffix = "") => {
    const s = str(text);
    let total = 0;
    for (const ch of s) total += utf8Bytes(ch);
    if (total <= maxBytes) return s;
    let suffixBytes = 0;
    for (const ch of suffix) suffixBytes += utf8Bytes(ch);
    const limit = Math.max(0, maxBytes - suffixBytes);
    let used = 0;
    let out = "";
    for (const ch of s) {
        const b = utf8Bytes(ch);
        if (used + b > limit) break;
        out += ch;
        used += b;
    }
    return out.trimEnd() + suffix;
};
const bark = (group, title, body, extra = {}) => {
    const fullTitle = clipUtf8(testMode ? `【🧪测试】 ${title}` : title, 240, "…");
    const safeBody = clipUtf8(body, 2800, "\n…（内容过长已截断）");
    const payload = { group, title: fullTitle, body: safeBody, action: "none" };
    for (const [key, value] of Object.entries(extra)) {
        if (value !== undefined && value !== null && value !== "") payload[key] = value;
    }
    return payload;
};
const fail = (reason, source) => [{ json: { unmatched: true, reason, source } }];

// 时间统一按 UTC+8 显示，不依赖 n8n 容器的 TZ 设置
const formatTimestamp = (value) => {
    const text = str(value).trim();
    if (!text) return "";
    const d = new Date(text);
    if (Number.isNaN(d.getTime())) return text;
    const hasZone = /(?:Z|[+-]\d{2}:?\d{2})$/i.test(text);
    const t = hasZone ? new Date(d.getTime() + 8 * 3600 * 1000) : d;
    const year = hasZone ? t.getUTCFullYear() : t.getFullYear();
    const month = hasZone ? t.getUTCMonth() + 1 : t.getMonth() + 1;
    const day = hasZone ? t.getUTCDate() : t.getDate();
    const hour = hasZone ? t.getUTCHours() : t.getHours();
    const minute = hasZone ? t.getUTCMinutes() : t.getMinutes();
    const second = hasZone ? t.getUTCSeconds() : t.getSeconds();
    const p = (n) => String(n).padStart(2, "0");
    return `${year} 年 ${p(month)} 月 ${p(day)} 日 ${p(hour)} 时 ${p(minute)} 分 ${p(second)} 秒`;
};
const removeTimestamp = (value) =>
    str(value).replace(/\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/, "").trim();

// 统一展示格式：空值用 —，阅读时间带单位
const DASH = "—";
const val = (value) => {
    const s = str(value).trim();
    return s || DASH;
};
const readingText = (value) => {
    const s = str(value).trim();
    return s ? `${s} 分钟` : DASH;
};

// HTML 实体解码与标签清理（用于解析 Spotify 等带 HTML 实体的正文）
const decodeHtml = (value) =>
    str(value)
        .replace(/<[^>]+>/g, " ")
        .replace(/&#x([0-9a-f]+);/gi, (m, hex) => {
            const code = parseInt(hex, 16);
            return Number.isNaN(code) ? m : String.fromCodePoint(code);
        })
        .replace(/&#(\d+);/g, (m, dec) => {
            const code = parseInt(dec, 10);
            return Number.isNaN(code) ? m : String.fromCodePoint(code);
        })
        .replace(/&quot;/gi, '"')
        .replace(/&apos;/gi, "'")
        .replace(/&lt;/gi, "<")
        .replace(/&gt;/gi, ">")
        .replace(/&nbsp;/gi, " ")
        .replace(/&amp;/gi, "&")
        .replace(/\s+/g, " ")
        .trim();

// 其乐标题太长：提取「游戏名 + 关键词」，做成 “xxx 发售特惠 / xxx 临时工” 这种短标题
// 关键词按帖子内容判断；临时工 feed 里的“已发售/折扣”帖子不应该一律标成临时工
const KEYLOL_KEYWORDS = [
    ["临时工", "临时工"],
    ["发售特惠", "发售特惠"],
    ["已发售", "发售特惠"],
    ["新史低", "新史低"],
    ["史低", "史低"],
    ["免费领取", "免费领取"],
    ["喜加一", "喜加一"],
    ["限时免费", "限时免费"],
    ["免费", "免费"],
    ["预售", "预售"],
    ["折扣", "折扣"],
    ["特惠", "特惠"],
    ["更新", "更新"]
];
const KEYLOL_KEYWORD_PATTERN = KEYLOL_KEYWORDS.map(([needle]) =>
    needle.replace(/[.*+?^$()|[\]\\]/g, "\\$&")
)
    .sort((a, b) => b.length - a.length)
    .join("|");
const KEYLOL_KEYWORD_SPLIT_RE = new RegExp(
    `(?:疑似|好像是|似乎是|好像|似乎|可能|貌似|突发|惊现|再现|又出|又见|又现|出现|迎来|开启|限时|首次|突然)?(?:${KEYLOL_KEYWORD_PATTERN})`
);
const KEYLOL_PLATFORM_ONLY_RE =
    /^(?:Steam|Epic|GOG|PSN|PS[45]|Xbox|NS2?|Switch|eShop|PC|主机|[阿土俄日港美欧国低外]区|\s|\/|\+|-)+$/i;

const cleanKeylolName = (raw) =>
    str(raw)
        .replace(/^[：:，,。！？?!、\s]+/, "")
        .split(/[|｜？?！!，,。；;]/)[0]
        .split(/\s+[-–—]\s+/)[0]
        .split(/\s*[￥¥$€£]\s*\d*/)[0]
        .split(/\s*[-+]?\d+(?:\.\d+)?\s*(?:%|折|元|块|刀|金币|(?:CNY|RMB|USD|HKD|JPY|ARS|TRY)(?![A-Za-z]))/i)[0]
        .split(/\s*(?:只要|仅售|仅需|现价|低至|直降|立减|打折|降价|免费送|白嫖)/)[0]
        .replace(/(?:疑似|好像|似乎|可能|貌似|[：:（(\s])+$/, "")
        .trim()
        .slice(0, 24);

const pickKeylolTagName = (tags) => {
    if (!Array.isArray(tags)) return "";
    for (const tag of tags) {
        const s = str(tag).trim();
        if (!s) continue;
        if (/^(?:app|sub|bundle)\/\d+/i.test(s) || /待更新/.test(s)) continue;
        return s.slice(0, 24);
    }
    return "";
};

const keylolKeyword = (text) => {
    const hit = KEYLOL_KEYWORDS.find(([needle]) => text.includes(needle));
    return hit ? hit[1] : "";
};
const keylolTitle = (value, fallbackKeyword, tags) => {
    const text = removeTimestamp(value);
    const match = text.match(/《([^》]+)》/);
    let name = match ? match[1].trim() : "";
    if (!name) {
        const cleaned = text.replace(/^(?:【[^】]*】|\[[^\]]*\]|\s)+/, "").trim();
        const kwMatch = cleaned.match(KEYLOL_KEYWORD_SPLIT_RE);
        if (kwMatch && kwMatch.index !== undefined) {
            const before = cleanKeylolName(cleaned.slice(0, kwMatch.index));
            const after = cleanKeylolName(
                cleaned
                    .slice(kwMatch.index + kwMatch[0].length)
                    .replace(/^[？?！!：:，,。、\s]*(?:来啦|来了|快冲|速冲|赶紧冲)?[？?！!：:，,。、\s]*/, "")
            );
            if (before && !KEYLOL_PLATFORM_ONLY_RE.test(before)) {
                name = before;
            } else if (after && !KEYLOL_PLATFORM_ONLY_RE.test(after)) {
                name = after;
            }
        } else {
            const candidate = cleanKeylolName(cleaned);
            if (candidate && !KEYLOL_PLATFORM_ONLY_RE.test(candidate)) {
                name = candidate;
            }
        }
        if (!name) {
            const tagName = pickKeylolTagName(tags);
            if (tagName) name = tagName;
        }
    }
    const keyword = keylolKeyword(text) || fallbackKeyword || "";
    if (name) return keyword ? `${name} ${keyword}` : name;
    return `其乐 ${keyword || "新帖"}`;
};

const findSpotifyIcon = (artist) => {
    const lower = str(artist).trim().toLowerCase();
    if (!lower) return "";
    if (SPOTIFY_ARTIST_ICONS[lower]) return SPOTIFY_ARTIST_ICONS[lower];
    for (const part of lower.split(/[,，&]|\bfeat\.?\b|\bft\.?\b/i)) {
        const key = part.trim();
        if (key && SPOTIFY_ARTIST_ICONS[key]) return SPOTIFY_ARTIST_ICONS[key];
    }
    return "";
};
const parseSpotifyEntry = (entry) => {
    const titleText = removeTimestamp(entry.title);
    const contentText = decodeHtml(entry.content);
    // RSSHub /spotify/artist/:id 常见正文：
    // "Once Upon a Christmas Eve" by Sample Artist, released at 2026-11-20 with 1 tracks.
    const byInContent = contentText.match(
        /\bby\s+(.+?)(?:,\s*released\b|\s+released\b|\s+with\s+\d+\s+tracks?\b|\.\s*$|$)/i
    );
    const byInTitle = titleText.match(/\bby\s+(.+)$/i);
    let artist = str((byInContent && byInContent[1]) || entry.author || (byInTitle && byInTitle[1]))
        .trim()
        .replace(/[.,;:\s]+$/, "");

    if (!artist) {
        const combined = `${titleText} ${contentText}`;
        for (const known of Object.keys(SPOTIFY_ARTIST_ICONS)) {
            const re = new RegExp(`\\b${known.replace(/[.*+?^$()|[\]\\]/g, "\\$&")}\\b`, "i");
            const m = combined.match(re);
            if (m) {
                artist = m[0];
                break;
            }
        }
    }

    const trackMatch = contentText.match(/\bwith\s+(\d+)\s+tracks?\b/i);
    const trackCount = trackMatch ? Number(trackMatch[1]) : NaN;
    let releaseType = "新专辑";
    if (!Number.isNaN(trackCount)) {
        releaseType = trackCount <= 1 ? "新单曲" : "新专辑";
    } else if (/\bsingle\b|单曲/i.test(`${titleText} ${contentText}`)) {
        releaseType = "新单曲";
    }

    const icon = findSpotifyIcon(artist);
    const title = artist ? `🎶 ${artist} 有${releaseType}发布` : `🎶 有${releaseType}发布`;
    return { title, icon, artist, trackCount };
};

// 从 RSS 条目中提取可作为 Bark 附图的图片 URL（跳过论坛表情、GitHub 小头像及非图片链接）
const BAD_IMAGE_RE =
    /\/static\/image\/smiley\/|avatars\.githubusercontent\.com|gravatar\.com|shields?\.io|(?:^|[\/_-])(?:emoji|smiley|emoticon|favicon|badge|pixel|1x1)(?:[\/_.-]|$)/i;
const IMAGE_EXT_RE = /\.(?:jpe?g|png|webp|avif|bmp|gif)(?:$|[?#])/i;
const IMAGE_CDN_RE = /\/(?:bfs|images?|img|media|photo|pics?|uploads?|store_item_assets)\//i;

const cleanImgUrl = (raw) => str(raw).replace(/&amp;/gi, "&").trim();
const isUsableImage = (raw, { allowGif = true, fromEnclosure = false } = {}) => {
    const url = cleanImgUrl(raw);
    if (!/^https?:\/\//i.test(url)) return false;
    if (BAD_IMAGE_RE.test(url)) return false;
    if (!allowGif && /\.gif(?:$|[?#])/i.test(url)) return false;
    if (fromEnclosure) return true;
    return IMAGE_EXT_RE.test(url) || IMAGE_CDN_RE.test(url);
};
const extractHtmlImages = (html) => {
    const urls = [];
    const text = str(html);
    for (const m of text.matchAll(/<img[^>]+\bsrc\s*=\s*["']([^"']+)["']/gi)) {
        urls.push(cleanImgUrl(m[1]));
    }
    return urls;
};
const extractRssImage = (entry, type) => {
    // Spotify / GitHub Releases 不从正文/enclosures 抓大图
    if (type === 4 || type === 5) return "";
    const content = str(entry.content);
    const htmlImgs = extractHtmlImages(content);

    // 直播间开播：取直播关键帧/封面图（过滤非图片网页链接）
    if (type === 3) {
        return htmlImgs.find((u) => isUsableImage(u, { allowGif: false })) || "";
    }

    // 其乐 Keylol：优先取非表情/非 gif 正文配图，找不到再按 Steam AppID 拼官方头图
    if (type === 1 || type === 6) {
        const hit = htmlImgs.find((u) => isUsableImage(u, { allowGif: false }));
        if (hit) return hit;
        const appMatch =
            content.match(/store\.steampowered\.com\/app\/(\d+)/i) ||
            content.match(/steamdb\.info\/app\/(\d+)/i) ||
            content.match(/[?&]appid=(\d+)/i);
        if (appMatch) {
            return `https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/${appMatch[1]}/header.jpg`;
        }
        return "";
    }

    // PT风向旗 / 通用 RSS：优先 enclosures 中的 image/*，其次正文首张有效图片
    const enclosures = Array.isArray(entry.enclosures) ? entry.enclosures : [];
    for (const enc of enclosures) {
        if (!enc || !enc.url) continue;
        const mime = str(enc.mime_type).toLowerCase();
        if (mime.startsWith("image/") || IMAGE_EXT_RE.test(str(enc.url))) {
            if (isUsableImage(enc.url, { fromEnclosure: true })) return cleanImgUrl(enc.url);
        }
    }
    return htmlImgs.find((u) => isUsableImage(u, { allowGif: false })) || "";
};

const { kind, payload } = $input.first().json;
testMode = payload.__test === true || payload.event_type === "save_entry";
if (kind !== "rss") return [];

const feed = payload.feed || {};
const feedTitle = str(feed.title);
const entries = Array.isArray(payload.entries) ? payload.entries : [];
// 没匹配到已知主题时，是否也按通用 RSS 转发（false = 返回 400「无匹配的 RSS 主题」）
const FORWARD_UNKNOWN_RSS = true;
// GitHub Releases 的 Miniflux 标题通常是 “Release notes from xxx”，
// 不一定包含 Github Releases 字样，所以再用 feed_url / 条目链接兜底识别
const feedUrl = `${str(feed.feed_url)} ${str(feed.site_url)}`;
const looksGitHubRelease =
    /github\.com\/[^/\s]+\/[^/\s]+\/releases/i.test(feedUrl) ||
    entries.some((entry) => /github\.com\/[^/\s]+\/[^/\s]+\/releases\//i.test(str(entry.url)));

let type = 0;
let baseTitle = "";
let baseIcon = "";
let feedBoard = "";
let feedRepo = "";
if (feedTitle.includes("临时工") && feedTitle.includes("其乐")) {
    type = 1;
    feedBoard = feedTitle.split("-")[0].trim() || "临时工";
    baseTitle = "🎉 其乐Keylol上有新的临时工消息 ！！！";
    baseIcon = KEYLOL_ICON;
} else if (feedTitle.includes("其乐") || /keylol/i.test(feedTitle)) {
    // 其乐的其它板块（购物心得、游戏情报等）
    type = 6;
    feedBoard = feedTitle.split("-")[0].trim() || "其乐";
    baseTitle = "🛒";
    baseIcon = KEYLOL_ICON;
} else if (feedTitle.includes("PT风向旗")) {
    type = 2;
    baseTitle = "⛓️ PT站点有新的动态 ！！！";
    baseIcon = PT_CHANNEL_ICON;
} else if (
    /直播|开播/.test(feedTitle) ||
    entries.some((entry) =>
        /(live\.bilibili\.com|douyu\.com|huya\.com|twitch\.tv|youtube\.com\/live)/i.test(str(entry.url))
    )
) {
    type = 3;
    const feedLooksLive = /直播|开播/.test(feedTitle);
    const liveName = feedLooksLive ? feedTitle.split(/直播间|直播|开播/)[0].trim() : "";
    baseTitle = liveName
        ? `📺 ${liveName}开播了 ！！！`
        : feedLooksLive
          ? `📺 ${feedTitle} ！！！`
          : "📺 有新的开播 ！！！";
    baseIcon = LIVE_STREAM_ICON;
} else if (/spotify/i.test(feedTitle) || /open\.spotify\.com/i.test(feedUrl)) {
    type = 4;
    baseTitle = "🎶 有新专辑发布";
} else if (
    feedTitle.includes("Github Realeases") ||
    feedTitle.includes("Github Releases") ||
    /release notes/i.test(feedTitle) ||
    looksGitHubRelease
) {
    type = 5;
    // 从 feed_url 或 “Release notes from xxx” 里取仓库名，标题更好认
    const repoFromUrl = (feedUrl.match(/github\.com\/[^/\s]+\/([^/\s]+)\/releases/i) || [])[1];
    const repoFromTitle = (feedTitle.match(/release notes from\s+(.+)$/i) || [])[1];
    const repo = str(repoFromUrl || repoFromTitle).trim();
    feedRepo = repo;
    baseTitle = repo ? `🔄 ${repo}` : "🔄";
} else {
    if (!FORWARD_UNKNOWN_RSS) return fail("无匹配的 RSS 主题", "RSS");
    type = 9;
    baseTitle = "📰";
}

if (!entries.length) return fail("RSS 消息没有 entries", "RSS");

const out = [];
for (const entry of entries) {
    let title = baseTitle;
    let icon = baseIcon;
    let spotifyInfo = null;
    if (type === 1) {
        // 其乐临时工 feed：先按帖子内容判关键词，内容里没有关键词时才退回“临时工”
        title = `🎉 ${keylolTitle(entry.title, "临时工", entry.tags)}`;
    } else if (type === 6) {
        // 其乐其它板块：提取游戏名 + 关键词（发售特惠 / 新史低 …）
        title = `🛒 ${keylolTitle(entry.title, "", entry.tags)}`;
    } else if (type === 9) {
        // 通用 RSS：标题用条目标题
        const postTitle = removeTimestamp(entry.title);
        title = postTitle ? `📰 ${postTitle}` : `${baseTitle} ${feedTitle}`.trim();
    } else if (type === 5) {
        // GitHub Releases：标题写明哪个仓库有新版本
        title = feedRepo ? `⬆️ ${feedRepo} 有新版本发布` : "⬆️ 有新版本发布";
    } else if (type === 4) {
        spotifyInfo = parseSpotifyEntry(entry);
        title = spotifyInfo.title;
        if (spotifyInfo.icon) icon = spotifyInfo.icon;
    }
    const boardLine = (type === 1 || type === 6) && feedBoard ? `【板块】${val(feedBoard)}\n` : "";
    const sourceLine = type === 9 ? `【来源】${val(feedTitle)}\n` : "";
    const trackText =
        spotifyInfo && !Number.isNaN(spotifyInfo.trackCount) ? `${spotifyInfo.trackCount} 首` : DASH;
    const body =
        type === 5
            ? `【版本】${val(removeTimestamp(entry.title))}\n` +
              `【发布时间】${val(formatTimestamp(entry.published_at))}\n\n` +
              `📄查看版本更新说明📄 ${val(entry.url)}`
            : type === 4
              ? `【作品】${val(removeTimestamp(entry.title))}\n` +
                `【艺人】${val(spotifyInfo && spotifyInfo.artist)}\n` +
                `【曲目数】${trackText}\n` +
                `【发布时间】${val(formatTimestamp(entry.published_at))}\n\n` +
                `🎧打开 Spotify🎧 ${val(entry.url)}`
              : type === 3
                ? `【标题】${val(removeTimestamp(entry.title))}\n\n` +
                  `📺进入直播间📺 ${val(entry.url)}`
                : boardLine +
                  sourceLine +
                  `【标题】${val(removeTimestamp(entry.title))}\n` +
                  `【发布时间】${val(formatTimestamp(entry.published_at))}\n` +
                  `【阅读时间】${readingText(entry.reading_time)}\n\n` +
                  `🔍查看详情🔍 ${val(entry.url)}`;
    const image = extractRssImage(entry, type);
    out.push({
        json: {
            bark: bark("RSS", title, body, { icon, image }),
            source: "RSS"
        }
    });
}
return out;

