    [["unraid"], ""],                 // unRAID 服务器
    [["pve", "proxmox"], ""],         // Proxmox VE 宿主机
    [["synology", "dsm"], ""]         // 群晖 Synology NAS
    // 新增其它系统示例：
    // [["ubuntu", "debian"], "https://cdn.jsdelivr.net/gh/selfhst/icons/png/ubuntu.png"],
];
