    const p = (n) => String(n).padStart(2, "0");
    return `${year} 年 ${p(month)} 月 ${p(day)} 日 ${p(hour)} 时 ${p(minute)} 分 ${p(second)} 秒`;
};

const normalize = (value) =>
    str(value)
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "");

const ICON_ALIAS = {
    postgres: "postgresql",
    pgsql: "postgresql",
    mongo: "mongodb",
    nodered: "node-red",
    "immich-server": "immich",
    "immich-machine-learning": "immich",
    "mastodon-web": "mastodon",
    "mastodon-streaming": "mastodon",
    "mastodon-sidekiq": "mastodon",
    "librespeed-speedtest": "librespeed",
    speedtest: "librespeed",
