function imageCandidates(image) {
    const out = new Set();
    const add = (value) => {
        const v = normalize(value);
        if (v) out.add(v);
    };
    let ref = str(image).trim();
    if (!ref) return [];
    ref = ref.split("@")[0];
    ref = ref.replace(/:[^/:]+$/, "");
    const parts = ref.split("/").filter(Boolean);
    if (parts.length > 1 && /[.:]/.test(parts[0])) parts.shift();
    const name = parts.pop() || "";
    const path = parts.join("/");

    add(name);
    add(path);
    add(path ? `${path}-${name}` : "");
    for (const segment of path.split("/")) {
        add(segment);
        add(segment.replace(/-releases$/, ""));
    }

    const suffixes = [
        "-server", "-app", "-web", "-api", "-worker", "-service",
        "-db", "-database", "-redis", "-postgres", "-postgresql",
        "-mysql", "-mariadb", "-machine-learning", "-ml", "-aio",
        "-latest", "-v2", "-v3", "-v4"
    ];
    for (const suffix of suffixes) {
        if (name.endsWith(suffix)) add(name.slice(0, -suffix.length));
    }

    const stopwords = new Set([
        "server", "service", "app", "web", "api", "worker", "latest",
        "release", "stable", "alpine", "slim", "base", "core", "main",
        "edge", "proxy", "static", "admin", "users", "push", "gateway",
        "messages", "media", "gifs", "unfurl", "snowflakes", "aio",
        "machine", "learning", "ml", "db", "database"
    ]);
    for (const token of name.split("-")) {
        if (token.length >= 3 && !stopwords.has(token)) add(token);
    }
    return [...out];
}

