const filesToCleanup = [];
for (const input of $input.all()) {
    const batchItems = Array.isArray(input.json.items) ? input.json.items.slice() : [];
    const claimedFiles = Array.isArray(input.json.claimedFiles) ? input.json.claimedFiles : [];
    if (!batchItems.length) {
        filesToCleanup.push(...claimedFiles);
        continue;
    }

    if (batchItems.length === 1) {
        const singleBark = { ...batchItems[0].bark };
        if (!singleBark.icon) singleBark.icon = MP_DEFAULT_ICON;
        if (singleBark.attach && !singleBark.image) singleBark.image = singleBark.attach;
        delete singleBark.attach;
        singleBark.title = clipUtf8(singleBark.title, 240, "…");
        singleBark.body = clipUtf8(singleBark.body, 2800, "\n…（内容过长已截断）");
        out.push({ json: { bark: singleBark, source: "MoviePilot", event: "transfer.complete" } });
        filesToCleanup.push(...claimedFiles);
        continue;
    }

    batchItems.sort((a, b) => {
        const ea = extractEpisodes(a)[0] || num(a.episode);
        const eb = extractEpisodes(b)[0] || num(b.episode);
        return ea - eb;
    });
    const meta = batchItems[0].meta || {};
    testMode = Boolean(batchItems[0].bark && String(batchItems[0].bark.title).startsWith("【🧪测试】"));

    const allEpisodes = [];
    for (const item of batchItems) allEpisodes.push(...extractEpisodes(item));
    const uniqueEpisodes = [...new Set(allEpisodes)].sort((a, b) => a - b);
    const episodeText = formatEpisodes(uniqueEpisodes);
    const totalSize = batchItems.reduce((sum, item) => sum + num(item.size), 0);
    const totalFiles = batchItems.reduce((sum, item) => sum + num((item.meta || {}).fileCount), 0);
    const title = `🎬 ${str(meta.show)} S${pad(meta.season)} ${episodeText} 已入库`;
    const body =
        `【集数】${episodeText}（共 ${uniqueEpisodes.length} 集）\n` +
        `【评分】${score(meta.score)}\n` +
        `【流行度】${val(meta.popularity)}\n` +
        `【类别】${val(meta.category)}\n` +
        `【时长】${val(meta.duration)}\n` +
        `【质量】${val(meta.quality)}\n` +
        `【编码格式】${val(meta.encode)}\n` +
        `【合计】${totalFiles} 个文件\n` +
        `【大小】${formatSize(totalSize)}\n\n` +
        `${linkJellyfin(meta.jellyfinUrl)}\n` +
        `${linkTMDB(meta.detailLink)}\n` +
        `${linkHomepage(meta.homepage)}`;

    out.push({
        json: {
            bark: bark("MoviePilot", title, body, { icon: meta.icon, image: meta.image || meta.attach }),
            source: "MoviePilot",
            event: "transfer.complete",
            aggregated: uniqueEpisodes.length || batchItems.length
        }
    });
    filesToCleanup.push(...claimedFiles);
}

// 输出全部构建成功后，再清理抢占到的 .processing 文件
if (filesToCleanup.length) {
    try {
        const fs = require("fs");
        for (const file of filesToCleanup) {
            try {
                fs.unlinkSync(file);
            } catch (e) {
                // 忽略
            }
        }
    } catch (e) {
        // 无 fs 权限时跳过
    }
}

return out;

/**
 * 刷出入库缓冲（文件队列）
 *
 * 由 Schedule Trigger 定时触发：读取缓冲目录，按「剧名+季」分组，
 * 满足「最后一条到达后静默满 TRANSFER_IDLE_SECONDS 秒」或「首条等待达 TRANSFER_MAX_WAIT_SECONDS 秒」
 * 即交给「合并入库通知」。
 *
 * 安全机制：
 * - 用 renameSync 原子抢占为 .processing，避免并发双发；
 * - 不在此节点提前删除 .processing，而是把路径交给「合并入库通知」构造成功后清理；
 * - 若下游意外中断导致 .processing 滞留超过 RECOVERY_SECONDS，自动恢复回 .json 重试一次。
 */

const BUFFER_DIR = "/home/node/.n8n/transfer_buffer"; // 与「入库缓冲」保持一致
const TRANSFER_IDLE_SECONDS = 20; // 最后一集到达后静默 20 秒再合并（避免连续入库被腰斩）
const TRANSFER_MAX_WAIT_SECONDS = 120; // 首集到达后最长等待 120 秒兜底必发
const RECOVERY_SECONDS = 300; // .processing 滞留 5 分钟视为异常中断，自动恢复重试一次
const STALE_SECONDS = 3600; // 清理超过 1 小时的残留 .tmp 或二次失败的 .processing

let fs = null;
try {
    fs = require("fs");
} catch (e) {
    fs = null;
}
if (!fs) return [];

const now = Date.now();

// 先检查是否有因异常中断遗留的 .processing 文件：首次滞留恢复为 .recovered.json 重试一次
try {
    for (const name of fs.readdirSync(BUFFER_DIR)) {
        const full = `${BUFFER_DIR}/${name}`;
        if (name.endsWith(".processing")) {
            try {
                const age = now - fs.statSync(full).mtimeMs;
                if (age > RECOVERY_SECONDS * 1000 && !name.includes(".recovered.")) {
                    const recovered = full.replace(/\.json\.processing$/, ".recovered.json");
                    fs.renameSync(full, recovered);
                } else if (age > STALE_SECONDS * 1000) {
                    fs.unlinkSync(full);
                }
            } catch (e) {
                // 忽略并发竞争
            }
        } else if (name.endsWith(".tmp")) {
            try {
                if (now - fs.statSync(full).mtimeMs > STALE_SECONDS * 1000) fs.unlinkSync(full);
            } catch (e) {
                // 忽略
            }
        }
    }
} catch (e) {
    return [];
}

let files = [];
try {
    files = fs.readdirSync(BUFFER_DIR).filter((name) => name.endsWith(".json"));
} catch (e) {
    return [];
}

const records = [];
for (const file of files) {
    try {
        const data = JSON.parse(fs.readFileSync(`${BUFFER_DIR}/${file}`, "utf8"));
        records.push({
            file,
            at: Number(data.at) || 0,
            transfer: data.transfer || {},
            bark: data.bark
        });
    } catch (e) {
        // 跳过损坏/写了一半的文件
    }
}

const groups = new Map();
for (const record of records) {
    const transfer = record.transfer;
    if (!transfer || transfer.kind !== "episode" || !record.bark) continue;
    const key = `${transfer.show}|S${transfer.season}`;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(record);
}

const out = [];
for (const list of groups.values()) {
    const times = list.map((record) => record.at || now);
    const firstAt = Math.min(...times);
    const lastAt = Math.max(...times);
    const idleReady = now - lastAt >= TRANSFER_IDLE_SECONDS * 1000;
    const maxWaitReady = now - firstAt >= TRANSFER_MAX_WAIT_SECONDS * 1000;
    if (!idleReady && !maxWaitReady) continue;

    // rename 抢占文件，避免两个刷出执行同时发送同一批
    const claimed = [];
    for (const record of list) {
        const source = `${BUFFER_DIR}/${record.file}`;
        const target = `${source}.processing`;
        try {
            fs.renameSync(source, target);
            claimed.push({ ...record, target });
        } catch (e) {
            // 已被其它执行处理
        }
    }
    if (!claimed.length) continue;

    out.push({
        json: {
            claimedFiles: claimed.map((record) => record.target),
            items: claimed.map((record) => ({
                episode: record.transfer.episode,
                episodes: Array.isArray(record.transfer.episodes) && record.transfer.episodes.length
                    ? record.transfer.episodes
                    : [record.transfer.episode],
                size: record.transfer.size,
                bark: record.bark,
                meta: record.transfer
            }))
        }
    });
}

return out;

/**
 * MoviePilot 通知（单节点）
 *
 * 统一处理 MoviePilot 的所有通知类型：
 *   - 订阅：subscribe.added / subscribe.complete / subscribe.modified / subscribe.deleted
 *   - 下载/入库：download.added / transfer.complete（入库额外输出 transfer 元数据供聚合）
 *   - 插件：plugin.triggered（刷流等）
 *   - 站内通知：notice.message（刷流、体育、站点私信、通用）
 *
 * 只处理 mp-* 来源，其它来源直接返回空数组，交给别的节点。
 */

// ======================= 可配置图标与链接 =======================
// MoviePilot 默认图标（所有 MP 通知在匹配不到媒体/站点图标时的统一兜底）
const MP_DEFAULT_ICON = ""; // 可选：MoviePilot 默认兜底图标 URL（留空则使用 Bark 默认图标）
// 体育赛事通知（AutoSports 插件）图标
const SPORTS_ICON = ""; // 可选：体育赛事通知图标 URL
// PT 站点图标映射（[站点关键词, 图标网址]，不区分大小写；未命中自动用 MP_DEFAULT_ICON）
const SITE_ICONS = [
  // 可选：按站点关键词匹配专属图标（从上到下依次包含匹配），例如：
  // ["站点关键词", "https://your-image-host.example.com/icons/site.png"]
];
// MoviePilot 与 Jellyfin 跳转地址
const MP_BASE_URL = "https://your-moviepilot.example.com"; // 修改为你的 MoviePilot 访问地址
const JELLYFIN_MOVIES = "https://your-jellyfin.example.com/web/#/movies.html?topParentId=YOUR_MOVIES_LIBRARY_ID&collectionType=movies"; // 可选：修改为你的 Jellyfin 电影库地址
const JELLYFIN_TV = "https://your-jellyfin.example.com/web/#/tv.html?topParentId=YOUR_TV_LIBRARY_ID&collectionType=tvshows"; // 可选：修改为你的 Jellyfin 剧集库地址
const JELLYFIN_SPORTS = "https://your-jellyfin.example.com/web/#/list?parentId=YOUR_SPORTS_LIBRARY_ID&serverId=YOUR_JELLYFIN_SERVER_ID"; // 可选：修改为你的 Jellyfin 体育库地址
// ===============================================================

let testMode = false;

const str = (v) => (v === null || v === undefined ? "" : String(v));
const num = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
};
const round = (v, digits = 2) => {
    const n = Number(v);
    if (!Number.isFinite(n)) return "";
    const factor = Math.pow(10, digits);
    return Math.round(n * factor) / factor;
};
const formatSize = (value) => {
    const n = num(value);
    if (n / 1000000000000 >= 1) return `${round(n / 1000000000000, 2)} TB`;
    if (n / 1000000000 >= 1) return `${round(n / 1000000000, 2)} GB`;
    return `${round(n / 1000000, 2)} MB`;
};
const lines = (v) => str(v).split("\n");
const after = (v, sep) => {
    const s = str(v);
    if (!sep) return s;
    const i = s.indexOf(sep);
    return i === -1 ? s : s.slice(i + sep.length);
};
const utf8Bytes = (ch) => {
    const cp = ch.codePointAt(0);
    if (cp <= 0x7f) return 1;
    if (cp <= 0x7ff) return 2;
    if (cp <= 0xffff) return 3;
    return 4;
};
const clipUtf8 = (text, maxBytes, suffix = "") => {
    const s = str(text);
    let total = 0;
    for (const ch of s) total += utf8Bytes(ch);
    if (total <= maxBytes) return s;
    let suffixBytes = 0;
    for (const ch of suffix) suffixBytes += utf8Bytes(ch);
    const limit = Math.max(0, maxBytes - suffixBytes);
    let used = 0;
    let out = "";
    for (const ch of s) {
        const b = utf8Bytes(ch);
        if (used + b > limit) break;
        out += ch;
        used += b;
    }
    return out.trimEnd() + suffix;
};
const bark = (group, title, body, extra = {}) => {
    const fullTitle = clipUtf8(testMode ? `【🧪测试】 ${title}` : title, 240, "…");
    const safeBody = clipUtf8(body, 2800, "\n…（内容过长已截断）");
    const payload = { group, title: fullTitle, body: safeBody, action: "none" };
    for (const [key, value] of Object.entries(extra)) {
        if (value !== undefined && value !== null && value !== "") payload[key] = value;
    }
    if (!payload.icon) payload.icon = MP_DEFAULT_ICON;
    return payload;
};
const fail = (reason, source) => [{ json: { unmatched: true, reason, source } }];

// 统一展示格式：空值统一用 —，评分保留一位小数，时长省略为 0 的单位
const DASH = "—";
const val = (value) => {
    const s = str(value).trim();
    return s || DASH;
};
const score = (value) => {
    const raw = str(value).trim();
    if (!raw) return DASH;
    const n = Number(raw);
    return Number.isFinite(n) ? n.toFixed(1) : raw;
};
const durationText = (hours, minutes) => {
    const h = Math.floor(num(hours));
    const m = Math.round(num(minutes));
    if (h && m) return `${h} 小时 ${m} 分钟`;
    if (h) return `${h} 小时`;
    if (m) return `${m} 分钟`;
    return DASH;
};
const formatMinutes = (minutes) => {
    const total = Math.round(num(minutes));
    if (total <= 0) return DASH;
    return durationText(Math.floor(total / 60), total % 60);
};
// TMDB 的 episode_run_time 是常见单集时长列表（不是总时长）：
// 单值直接展示；多值展示“最短 ~ 最长（平均）”；无数据时保持 —
const mediaDurationText = (mi = {}) => {
    const rawList = Array.isArray(mi.episode_run_time) ? mi.episode_run_time : [];
    const valid = rawList.map(num).filter((v) => v > 0);
    if (valid.length === 1) return formatMinutes(valid[0]);
    if (valid.length > 1) {
        const min = Math.min(...valid);
        const max = Math.max(...valid);
        if (min === max) return formatMinutes(min);
        const avg = Math.round(valid.reduce((a, b) => a + b, 0) / valid.length);
        return `${formatMinutes(min)} ~ ${formatMinutes(max)}（平均 ${formatMinutes(avg)}）`;
    }
    const rt = num(mi.runtime);
    return rt > 0 ? formatMinutes(rt) : DASH;
};
const linkMP = (url) => `🗃️在MP中查看🗃️ ${val(url)}`;
const linkTMDB = (url) => `🔗在TMDB中查看🔗 ${val(url)}`;
const linkJellyfin = (url) => `🎞️在Jellyfin中查看🎞️ ${val(url)}`;
const linkHomepage = (url) => `🌐查看影视官网🌐 ${val(url)}`;
const linkPT = (url) => `🔍在PT站中查看🔍 ${val(url)}`;

// ======================= 可调参数 =======================
const BRUSHFLOW_PLUGIN_ID = "BrushFlow"; // 刷流插件 ID（插件页深链用）
const FORWARD_GENERIC_MP_NOTICE = true; // 通用 MoviePilot notice.message 是否也转发
const DROP_DUPLICATE_GENERIC_NOTICE = true; // 丢弃与已格式化事件重复的通用通知
const DROP_DUPLICATE_BRUSHFLOW_NOTICE = true; // 刷流的纯文本“种子下载”通知不再发
const FORWARD_SUBSCRIBE_MODIFIED = true; // 是否转发「真实」的订阅修改通知

// 只有这些字段变化时不推送（MoviePilot 自己维护的记账字段，兼容 v3/v2 字段名）
